import{H as e,_t as t,nt as n,rt as r}from"./chunks/framework.ByJSXnli.js";var i=JSON.parse(`{"title":"Algorithms and defaults","description":"","frontmatter":{},"headers":[],"relativePath":"reference/algorithms.md","filePath":"reference/algorithms.md"}`),a={name:`reference/algorithms.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="algorithms-and-defaults" tabindex="-1">Algorithms and defaults <a class="header-anchor" href="#algorithms-and-defaults" aria-label="Permalink to “Algorithms and defaults”">​</a></h1><p>The algorithms of the core package, the operators each one requires and the value it takes for every setting you omit. <a href="/guide/fundamentals/algorithms.html">Algorithms</a> explains how to choose and construct one.</p><h2 id="search-algorithms" tabindex="-1">Search algorithms <a class="header-anchor" href="#search-algorithms" aria-label="Permalink to “Search algorithms”">​</a></h2><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Algorithm</th><th>Search state</th><th>Requires</th><th>Optional operators</th></tr></thead><tbody><tr><td><code>GeneticAlgorithm&lt;T&gt;</code></td><td><code>PopulationState&lt;T&gt;</code></td><td><code>Creator</code>, <code>Crossover</code>, <code>Mutator</code></td><td><code>Selector</code>, <code>Evaluator</code>, <code>Refiner</code>, <code>Terminator</code>, <code>Interceptor</code></td></tr><tr><td><code>EvolutionStrategy&lt;T&gt;</code></td><td><code>PopulationState&lt;T&gt;</code></td><td><code>Creator</code>, <code>Mutator</code></td><td><code>Crossover</code>, <code>Selector</code>, <code>Evaluator</code>, <code>Refiner</code>, <code>MutationStrengthAdaptation</code>, <code>Interceptor</code></td></tr><tr><td><code>NSGA2&lt;T&gt;</code></td><td><code>PopulationState&lt;T&gt;</code></td><td><code>Creator</code>, <code>Crossover</code>, <code>Mutator</code></td><td><code>Selector</code>, <code>Replacer</code>, <code>Evaluator</code>, <code>Refiner</code>, <code>Interceptor</code></td></tr><tr><td><code>HillClimber&lt;T&gt;</code></td><td><code>SingleSolutionState&lt;T&gt;</code></td><td><code>Creator</code>, <code>Mutator</code></td><td><code>Evaluator</code>, <code>Refiner</code>, <code>Interceptor</code></td></tr></tbody></table></div><p><code>For(problem, ...)</code> and <code>For(searchSpace, ...)</code> fill missing required operators from <a href="#operator-recommendations">recommendations</a>. Optional operators are never filled from recommendations.</p><h2 id="defaults" tabindex="-1">Defaults <a class="header-anchor" href="#defaults" aria-label="Permalink to “Defaults”">​</a></h2><p>Each algorithm reads its defaults from a public class, such as <code>GeneticAlgorithmDefaults</code>. Direct construction, <code>Create(...)</code> and <code>For(...)</code> use the same values.</p><h3 id="geneticalgorithmdefaults" tabindex="-1"><code>GeneticAlgorithmDefaults</code> <a class="header-anchor" href="#geneticalgorithmdefaults" aria-label="Permalink to “GeneticAlgorithmDefaults”">​</a></h3><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>PopulationSize</code></td><td>100</td></tr><tr><td><code>MaximumGenerations</code></td><td>1000</td></tr><tr><td><code>MutationRate</code></td><td>0.1</td></tr><tr><td><code>Elites</code></td><td>1</td></tr><tr><td><code>Selector</code></td><td><code>TournamentSelector</code> of size 2</td></tr><tr><td><code>Evaluator</code></td><td><code>ProblemEvaluator</code></td></tr></tbody></table></div><h3 id="evolutionstrategydefaults" tabindex="-1"><code>EvolutionStrategyDefaults</code> <a class="header-anchor" href="#evolutionstrategydefaults" aria-label="Permalink to “EvolutionStrategyDefaults”">​</a></h3><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>PopulationSize</code></td><td>100</td></tr><tr><td><code>NumberOfChildren</code></td><td>100</td></tr><tr><td><code>Strategy</code></td><td><code>Plus</code></td></tr><tr><td><code>MaximumGenerations</code></td><td>1000</td></tr><tr><td><code>Selector</code></td><td><code>RandomSelector</code></td></tr><tr><td><code>Evaluator</code></td><td><code>ProblemEvaluator</code></td></tr></tbody></table></div><h3 id="nsga2defaults" tabindex="-1"><code>NSGA2Defaults</code> <a class="header-anchor" href="#nsga2defaults" aria-label="Permalink to “NSGA2Defaults”">​</a></h3><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>PopulationSize</code></td><td>100</td></tr><tr><td><code>MaximumGenerations</code></td><td>1000</td></tr><tr><td><code>MutationRate</code></td><td>0.1</td></tr><tr><td><code>Selector</code></td><td><code>ParetoCrowdingTournamentSelector</code>, dominating on equal values</td></tr><tr><td><code>Replacer</code></td><td><code>ParetoCrowdingReplacer</code>, dominating on equal values</td></tr><tr><td><code>Evaluator</code></td><td><code>ProblemEvaluator</code></td></tr></tbody></table></div><h3 id="hillclimberdefaults" tabindex="-1"><code>HillClimberDefaults</code> <a class="header-anchor" href="#hillclimberdefaults" aria-label="Permalink to “HillClimberDefaults”">​</a></h3><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>Direction</code></td><td><code>FirstImprovement</code></td></tr><tr><td><code>MaxNeighbors</code></td><td>100</td></tr><tr><td><code>BatchSize</code></td><td>100</td></tr><tr><td><code>Evaluator</code></td><td><code>ProblemEvaluator</code></td></tr></tbody></table></div><p>A <code>MaximumGenerations</code> of <code>null</code> lets a run end on its terminator alone. Defaults are starting points, not tuned values. Record the values you rely on when a result must stay reproducible.</p><h2 id="operator-recommendations" tabindex="-1">Operator recommendations <a class="header-anchor" href="#operator-recommendations" aria-label="Permalink to “Operator recommendations”">​</a></h2><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Source</th><th>Creator</th><th>Crossover</th><th>Mutator</th></tr></thead><tbody><tr><td><code>PermutationSearchSpace</code></td><td><code>RandomPermutationCreator</code></td><td><code>EdgeRecombinationCrossover</code></td><td><code>InversionMutator</code></td></tr><tr><td><code>TravelingSalesmanProblem</code></td><td>none</td><td><code>OrderCrossover</code></td><td>none</td></tr></tbody></table></div><p>A problem&#39;s recommendation wins over its search space&#39;s.</p><h2 id="algorithms-that-wrap-or-combine-algorithms" tabindex="-1">Algorithms that wrap or combine algorithms <a class="header-anchor" href="#algorithms-that-wrap-or-combine-algorithms" aria-label="Permalink to “Algorithms that wrap or combine algorithms”">​</a></h2><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Algorithm</th><th>Created with</th><th>Does</th></tr></thead><tbody><tr><td><code>PipelineAlgorithm</code></td><td><code>first.Then(second)</code></td><td>Runs each stage to completion and starts the next from its last state</td></tr><tr><td><code>CycleAlgorithm</code></td><td><code>first.CycleWith(second)</code></td><td>Repeats its stages in order, each turn continuing from the last state</td></tr><tr><td><code>StateTerminatedAlgorithm</code></td><td><code>algorithm.TerminatedBy(terminator)</code></td><td>Stops the inner algorithm when a terminator fires</td></tr><tr><td><code>OperatorCountBudgetAlgorithm</code></td><td><code>LimitedToInvocations</code>, <code>LimitedToCandidates</code>, <code>LimitedToCount</code></td><td>Stops when counted operator work reaches a limit</td></tr><tr><td><code>OperatorDurationBudgetAlgorithm</code></td><td><code>algorithm.LimitedToDuration(limit, placement)</code></td><td>Stops when timed operator work reaches a limit</td></tr><tr><td><code>AlgorithmDurationBudgetAlgorithm</code></td><td><code>algorithm.LimitedToDuration(limit)</code></td><td>Stops when the algorithm&#39;s own running time reaches a limit</td></tr><tr><td><code>NamedAlgorithm</code></td><td><code>algorithm.Named(name)</code></td><td>Gives an algorithm a name that selections can find</td></tr><tr><td><code>SharingAlgorithm</code></td><td><code>algorithm.Sharing(configurations)</code></td><td>Keeps one executor for the listed configurations across child scopes</td></tr></tbody></table></div>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};